class Solution {
    class Node {
        int val;
        boolean hasApple;
        List<Node> neighbors = new ArrayList<>();

        public Node(int val, boolean hasApple) {
            this.val = val;
            this.hasApple = hasApple;
        }
    }

    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(i, hasApple[i]);
        }

        for (int[] edge : edges) {
            int x = edge[0];
            int y = edge[1];
            nodes[x].neighbors.add(nodes[y]);
            nodes[y].neighbors.add(nodes[x]);
        }

        int[][] memo = new int[n][2];
        for (int i = 0; i < n; i++) {
            Arrays.fill(memo[i], -1);
        }

        return minTime(nodes[0], memo) - 1;
    }

    private int minTime(Node node, int[][] memo) {
        if (memo[node.val][0] != -1) {
            return memo[node.val][0];
        }

        int minTime = 0;
        for (Node neighbor : node.neighbors) {
            minTime += minTime(neighbor, memo);
        }

        if (node.hasApple) {
            minTime += 2;
        }

        memo[node.val][0] = minTime;
        return minTime;
    }
}
