private int dfs(String s, int start, Set<String> seen) {
  if (start == s.length()) {
    return seen.size();
  }
  int max = 0;
  for (int end = start + 1; end <= s.length(); end++) {
    String sub = s.substring(start, end);
    if (seen.add(sub)) {
      max = Math.max(max, dfs(s, end, seen));
      seen.remove(sub);
    }
  }
  return max;
}

