public static void oddEvenSwap(int[] A) {
    // Initialize the sorted array
    int[] sorted = new int[A.length];

    // Initialize the indices of the odd-indexed and even-indexed elements
    int oddIndex = 0;
    int evenIndex = A.length - 1;

    // Iterate over the input array
    for (int i = 0; i < A.length; i++) {
        // If the current element is odd, add it to the sorted array
        if (A[i] % 2 == 1) {
            sorted[oddIndex] = A[i];
            oddIndex++;
        } else { // If the current element is even, add it to the sorted array
            sorted[evenIndex] = A[i];
            evenIndex--;
        }
    }

    // Copy the sorted array back to the input array
    for (int i = 0; i < A.length; i++) {
        A[i] = sorted[i];
    }
}
